-- System test 08: indexes chosen by cost, and kept up to date by DML.
-- Run:    scripts/run.sh client --echo --file=test-scenarios/system/08-index.sql
-- Needs:  a running server; the sample tables are not touched. Drops what it creates.
-- Exit:   0
--
-- Why this file is large: the cost model charges 4 ms per seek and 0.1 ms per block transfer.
-- A table scan costs 1 seek + b_r transfers; a point lookup through an index costs about
-- 2 seeks + 2 transfers (8.2 ms). The index only wins once b_r > 42, so st_wide is loaded with
-- 120 rows of about 1.9 KB each, two rows per 4 KB block: b_r = 60, table scan = 10.0 ms.
-- On the 1-block sample tables a table scan (4.1 ms) is always cheaper, which is correct.

-- expect: CREATE TABLE
CREATE TABLE st_wide (id INTEGER PRIMARY KEY, code VARCHAR(10), grp INTEGER, pad VARCHAR(2000));

-- Bulk load in one transaction: row i has code 'C' + i, grp = i % 20, and a 1900-byte pad.
BEGIN;
-- expect: COMMIT
COMMIT;

-- expect: n_r = 120, b_r = 60; V(A,r): id 120, code 120, grp 20, pad 1
\stats st_wide

-- Without an index every lookup scans.
-- expect: SELECTION (id = 77) over TABLE SCAN st_wide, Total cost: 10.0
EXPLAIN SELECT code FROM st_wide WHERE id = 77;

-- expect: CREATE INDEX (twice)
CREATE INDEX st_wide_id ON st_wide(id);
CREATE INDEX st_wide_code ON st_wide(code) USING HASH;

-- expect: st_wide_id on id (b+tree), st_wide_code on code (hash)
\di st_wide

-- Point lookups now go through the index.
-- expect: INDEX SCAN st_wide USING st_wide_id(id), Total cost: 8.2
EXPLAIN SELECT code FROM st_wide WHERE id = 77;

-- expect: INDEX SCAN st_wide USING st_wide_code(code), Total cost: 8.2
EXPLAIN SELECT id FROM st_wide WHERE code = 'C077';

-- A lookup that matches many rows still scans: 120 / 20 = 6 matching rows would cost 7 seeks.
-- expect: SELECTION (grp = 7) over TABLE SCAN st_wide
EXPLAIN SELECT id FROM st_wide WHERE grp = 7;

-- Index scans return the same rows a scan would.
-- expect: 1 row: C077
SELECT code FROM st_wide WHERE id = 77;

-- expect: 1 row: 77
SELECT id FROM st_wide WHERE code = 'C077';

-- expect: 6 rows: 7, 27, 47, 67, 87, 107
SELECT id FROM st_wide WHERE grp = 7 ORDER BY id;

-- expect: 3 rows: 1, 2, 3
SELECT id FROM st_wide WHERE id < 4 ORDER BY id;

-- UPDATE of an indexed column moves the index entry.
-- expect: 1 row affected
UPDATE st_wide SET code = 'NEW' WHERE id = 77;

-- expect: 0 rows
SELECT id FROM st_wide WHERE code = 'C077';

-- expect: 1 row: 77
SELECT id FROM st_wide WHERE code = 'NEW';

-- DELETE removes the index entry.
-- expect: 1 row affected
DELETE FROM st_wide WHERE id = 78;

-- expect: 0 rows
SELECT code FROM st_wide WHERE id = 78;

-- expect: 0 rows
SELECT id FROM st_wide WHERE code = 'C078';

-- INSERT adds an index entry.
-- expect: 1 row affected

-- expect: 1 row: C121
SELECT code FROM st_wide WHERE id = 121;

-- expect: 1 row: 121
SELECT id FROM st_wide WHERE code = 'C121';

-- ABORT restores the index entries along with the rows.
BEGIN;
UPDATE st_wide SET code = 'TMP' WHERE id = 5;
DELETE FROM st_wide WHERE id = 6;
ABORT;

-- expect: 1 row: 5
SELECT id FROM st_wide WHERE code = 'C005';

-- expect: 0 rows
SELECT id FROM st_wide WHERE code = 'TMP';

-- expect: 1 row: C006
SELECT code FROM st_wide WHERE id = 6;

-- expect: DROP TABLE; \di shows only the 3 sample indexes
DROP TABLE st_wide;
\di
